'use strict';
// Presentation groups are admitted by the project, never inferred from byte hashes.
function currentProject(){return state.projects.find(p=>p.id===state.project);}
function currentCollection(){return currentProject()?.collections.find(c=>c.id===state.category);}
function drawWorkNavigation(){
 const p=currentProject(), collections=(p?.collections||[]).filter(c=>c.top_level!==false);$('search').placeholder='Search works, scenes, cels or cues…';
 $('projects').replaceChildren(navButton('All projects',state.projects.length,state.project==='all',()=>chooseProject('all'),'◫'));
 state.projects.forEach(p=>$('projects').append(navButton(p.label,p.work_count,state.project===p.id,()=>chooseProject(p.id),p.label.slice(0,1))));
 $('categories').replaceChildren();
 collections.forEach(c=>$('categories').append(navButton(c.count_state?c.count_label:c.label,c.count_state?c.count_value:c.count,state.category===c.id,()=>chooseCollection(c.id))));
 $('heading').textContent=p?p.label:'Your projects';
 $('subheading').textContent=p?'One card per work. Open a work for its versions, languages and files.':'Choose a project to browse its organized collections.';
 const stats=document.querySelector('.stats');stats.replaceChildren();
 const highlights=p?collections.slice(0,4).map(c=>[c.count_value,c.count_label]):[[state.projects.length,'projects'],[state.projects.reduce((n,p)=>n+p.work_count,0),'organized works']];
 highlights.forEach(([n,label])=>{const s=node('div');s.append(node('span','',fmt.format(n)),node('small','',label));stats.append(s);});
 const snapshots=$('snapshot');snapshots.replaceChildren();snapshots.disabled=!p;
 if(p){snapshots.append(new Option('Pinned · '+p.commit.slice(0,10),p.commit));p.refs.forEach(([n,c])=>{if(c!==p.commit)snapshots.append(new Option(n.replace(/^refs\/(heads|remotes|tags)\//,'')+' · '+c.slice(0,8),c));});}
 else snapshots.append(new Option('Choose a project',''));
 const controls=$('work-controls');controls.replaceChildren();
 const collection=currentCollection();
 if(collection){
  const states=node('select');states.setAttribute('aria-label','Work status');states.append(new Option('All statuses',''));Object.keys(collection.states).forEach(s=>states.append(new Option(s,s)));states.value=state.workState;states.onchange=()=>{state.workState=states.value;state.facet='' ;drawWorkNavigation();load();};controls.append(states);
  const facets=node('div','facet-buttons');const counts=(state.workState?collection.state_facets?.[state.workState]:collection.facets)||{};const choices=['',...Object.keys(counts)];choices.forEach(f=>{const b=node('button','button secondary'+(state.facet===f?' chosen':''),f?(f+' ('+counts[f]+')'):'All');b.onclick=()=>{state.facet=f;drawWorkNavigation();load();};facets.append(b);});controls.append(facets);
 }
 const technical=$('technical');technical.hidden=!p;technical.textContent='Technical records ('+fmt.format(p?.records||0)+')';
 document.querySelector('main footer').textContent='Works are grouped using the project’s catalog rules. Registered status reflects this Git snapshot; remote delivery and cache presence are separate facts.';
}
async function chooseCollection(id){state.mode='works';state.category=id;state.searchKind='';state.facet='';state.q='';$('search').value='';state.workState=currentCollection()?.count_state||'';drawNavigation();await load();}
function workCard(work){const b=node('button','asset-card work-card');b.setAttribute('aria-label','Open '+work.title);const top=node('div','card-top');top.append(node('span','glyph',glyph(work.icon)),node('span','tag',work.category));const body=node('div','card-body');body.append(node('h3','',work.title),node('div','work-status',work.state==='Registered'?'Registered':work.state+' · registered'));const footer=node('div','card-footer');footer.append(node('span','',work.facets.join(' · ')),node('span','','Open work →'));body.append(footer);b.append(top,body);b.onclick=()=>inspectWork(work);return b;}
async function loadWorks(more=false){const gen=++state.generation;notice('');if(!more){state.offset=0;state.rows=[];$('assets').replaceChildren(node('div','empty','Loading works…'));}
 try{const data=await api('/api/works',{project:state.project,collection:state.category,state:state.workState,facet:state.facet,q:state.q,offset:state.offset});if(gen!==state.generation)return;if(Object.entries(data.snapshots).some(([id,c])=>currentProject()?.id!==id||currentProject().commit!==c))throw Error('Snapshot changed. Refresh the view.');state.rows.push(...data.items);state.offset=state.rows.length;$('assets').replaceChildren(...state.rows.map(workCard));if(!state.rows.length)$('assets').append(node('div','empty','No works match this selection.'));const c=currentCollection();$('category-heading').textContent=c?.label||'Works';$('result-count').textContent=fmt.format(data.total)+' '+(state.workState?state.workState.toLowerCase()+' ':'')+(currentCollection()?.label.toLowerCase()||'works');$('more').hidden=state.offset>=data.total;}catch(e){notice(e.message);}}
function loadProjectOverview(){notice('');$('more').hidden=true;$('category-heading').textContent='Projects';$('result-count').textContent=state.projects.length+' projects';$('assets').replaceChildren(...state.projects.map(p=>{const card=node('article','asset-card project-dashboard-card'),body=node('div','card-body');body.append(node('h3','',p.label),node('p','',p.collections.length?p.work_count+' organized works':'Catalog rules not configured'));p.collections.slice(0,4).forEach(c=>body.append(node('p','project-summary',c.count_label+' · '+c.count_value)));const actions=node('div','project-dashboard-actions');const catalog=node('button','button secondary','Open catalog');catalog.onclick=()=>chooseProject(p.id);const storage=node('button','button secondary','Manage objects');storage.onclick=()=>openObjectManager(p.id);const coverage=node('button','button secondary','Metadata coverage');coverage.onclick=()=>openCoverage(p.id);actions.append(catalog,storage,coverage);body.append(actions);card.append(body);return card;}));}
async function inspectWork(work){$('back-work').textContent='← Back to work';state.selected={work};$('back-work').hidden=true;$('inspector').hidden=false;$('scrim').hidden=false;$('close').focus();$('asset-title').textContent=work.title;$('asset-id').textContent=work.id;$('asset-badges').replaceChildren(node('span','badge',work.category),node('span','badge',work.state));$('tabs').replaceChildren();$('detail').replaceChildren(node('p','muted','Loading this work…'));
 try{const d=await api('/api/work',{project:work.project,collection:work.collection,id:work.id,snapshot:state.projects.find(p=>p.id===work.project).commit});if(state.selected?.work!==work)return;state.selected.workDetails=d;drawAncestry(d);state.tab='Overview';drawWorkDetail();}catch(e){$('detail').replaceChildren(node('p','callout',e.message));}}
function memberButton(card){const b=node('button','member-button');b.append(node('strong','',card.title),node('small','',card.id));b.onclick=()=>openWorkMember(card);return b;}
function drawWorkDetail(){const selected=state.selected,d=selected?.workDetails;if(!d)return;const w=d.work,area=$('detail');area.replaceChildren();$('tabs').replaceChildren(...['Overview','Browse','Versions','Deliveries','Files'].map(t=>{const b=node('button',state.tab===t?'active':'',t);b.onclick=()=>{state.tab=t;drawWorkDetail();};return b;}));
 if(state.tab==='Overview'){const manage=node('button','button secondary','Manage this work’s objects');manage.onclick=()=>openObjectManager(w.project,w);area.append(manage);const s=section('Current work');field(s,'Registered status',w.state);if(w.version)field(s,'Current version',w.version);if(w.facets.length)field(s,'Collection',w.facets.join(' · '));field(s,'Registered versions',d.versions.length||'Not declared by this catalog rule');area.append(s);if(d.children_total){const children=node('button','button','Browse child items ('+d.children_total+')');children.onclick=()=>{state.tab='Browse';drawWorkDetail();};area.append(children);}if(d.deliveries.length){const out=section('Deliverable files');d.deliveries.slice(0,12).forEach(c=>out.append(memberButton(c)));area.append(out);}const b=node('button','button secondary','Inspect source record');b.onclick=()=>openWorkMember(d.root);area.append(b);}
 if(state.tab==='Browse'){browseChildren();}
 if(state.tab==='Versions'){versionComparisonControls(d,area);if(!d.versions.length)area.append(node('p','muted','No version interpretation is configured for this work.'));d.versions.forEach(v=>{const s=node('div','stream');s.append(node('strong','',v.label.replace(/^version\//,'')),node('p','',v.current?'Current registered selection':'Retained version'));area.append(s);});}
 if(state.tab==='Deliveries'){d.deliveries.forEach(c=>area.append(memberButton(c)));if(!d.deliveries.length)area.append(node('p','muted','No delivery-file mapping configured for this work.'));area.append(node('p','callout','These are registered deliverable files. Remote targets and contents have not been checked now.'));}
 if(state.tab==='Files'){const selector=node('select');selector.setAttribute('aria-label','Supporting file type');selector.append(new Option('All related files ('+w.member_count+')',''));Object.entries(d.member_categories).forEach(([k,n])=>selector.append(new Option(k+' ('+n+')',k)));selector.value=selected.memberCategory||'';selector.onchange=async()=>{selected.memberCategory=selector.value;try{const more=await api('/api/work',{project:w.project,collection:w.collection,id:w.id,snapshot:d.commit,category:selector.value});if(state.selected!==selected)return;selected.workDetails=more;drawWorkDetail();}catch(e){notice(e.message);}};area.append(selector,node('p','muted','Versions and related files belong to this work; they are not extra works.'));d.members.forEach(c=>area.append(memberButton(c)));if(d.members.length<d.member_total){const b=node('button','button secondary','Show more files');b.onclick=async()=>{b.disabled=true;try{const next=await api('/api/work',{project:w.project,collection:w.collection,id:w.id,snapshot:d.commit,category:selected.memberCategory||'',offset:d.members.length});if(state.selected!==selected)return;d.members.push(...next.members);drawWorkDetail();}catch(e){notice(e.message);b.disabled=false;}};area.append(b);}}
}

function openWorkMember(card){const work=state.selected?.work;if(work){$('back-work').hidden=false;$('back-work').onclick=()=>inspectWork(work);}inspect(card);}
